// Push-Button LED Toggle
// Each press flips the LED's on/off state — not "on while held."

const int BUTTON_PIN = 2;
const int LED_PIN = 13;

bool ledState = false;
bool lastButtonReading = HIGH; // HIGH = not pressed, thanks to INPUT_PULLUP

void setup() {
  pinMode(BUTTON_PIN, INPUT_PULLUP);
  pinMode(LED_PIN, OUTPUT);
}

void loop() {
  bool currentReading = digitalRead(BUTTON_PIN);

  // A press is the MOMENT the reading changes from HIGH to LOW —
  // not every loop where it happens to read LOW.
  if (currentReading == LOW && lastButtonReading == HIGH) {
    ledState = !ledState;
    digitalWrite(LED_PIN, ledState);
    delay(30); // crude debounce — see the Rotary Encoder project for a cleaner approach
  }

  lastButtonReading = currentReading;
}
